function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Background: green hills
  for (let i = 0; i < width; i++) {
    line(i, 0, i, height);
    line(i, height, i, 0);
  }

  // Sun
  const sunColor = "#e08a72";
  brush.fillStyle = sunColor;
  brush.circle(width / 2, height / 2, 50);

  // Ground
  fill("#f9f9f9");
  brush.rect(0, 0, width, height * 0.5);

  // Detail
  // Draw multiple points on the ground to create a more detailed effect
  for (let i = 0; i < width; i++) {
    for (let j = 0; j < height; j++) {
      if (j > 0 && j < height - 1) {
        const detailColor = "#a1a1a1";
        brush.fillStyle = detailColor;
        brush.circle(i, j, 10);
      }
    }
  }

  // Sky
  fill("#f4e4ef");
  brush.circle(0, 0, 50);
}
