function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  fill(0, 255, 0); // sky
  brush.beginShape(3); // cone-shaped shape

  // start the cone at (200, 200), height 100, and radius 50
  // using 3 vertices to define the cone shape
  for (let i = 0; i < 3; i++) {
    let angle = i * 6.28 / 3;
    let x = 200 + 50 * Math.cos(angle);
    let y = 200 + 50 * Math.sin(angle);
    brush.vertex(x, y);
  }

  // end the cone
  brush.endShape(true);

  // draw ground at (0, 400)
  fill(255, 255, 255); // ground
  brush.circle(0, 400, 50);

  // add details around the ground
  fill(255, 100, 0); // details
  brush.circle(200, 350, 30);
  brush.circle(200, 300, 30);
  brush.circle(200, 250, 30);

  // draw sun at (200, 150)
  fill(255, 255, 0); // sun
  brush.circle(200, 150, 50);

  // end the scene
  brush.endShape(false);
}
