function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Setting the sun's position
  let sunX = 400;
  let sunY = height / 2;

  // Drawing the earth as a background
  fill(0x333);
  circle(sunX, sunY, 50);

  // Drawing the horizon as a line
  stroke(0x000);
  line(sunX, sunY, sunX + width, sunY);

  // Setting the sun's position for the sunset
  sunX += 50; // Move the sun to the right

  // Drawing the sun as a new background
  fill(0xff5000);
  circle(sunX, sunY, 50);

  // Drawing the sunset as a line
  stroke(0x000);
  line(sunX, sunY, sunX + width, sunY);
}
