const canvas = createCanvas(800, 600, WEBGL);
const ctx = canvas.getContext('webgl');

// Set up the sky
ctx.fillStyle = '#808080';
ctx.fillRect(0, 0, canvas.width, canvas.height);

// Set up the ground
ctx.fillStyle = '#404040';
ctx.fillRect(0, canvas.height - 300, canvas.width, 200);

// Set up the hills
ctx.fillStyle = '#333333';
ctx.beginPath();
ctx.moveTo(100, 0);
ctx.lineTo(300, 0);
ctx.lineTo(300, 300);
ctx.lineTo(100, 300);
ctx.closePath();
ctx.fill();

// Draw the sunset
ctx.fillStyle = '#ff0000';
ctx.fillRect(100, 100, 400, 100);
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 5;
ctx.lineDashOffset = 5;
ctx.beginPath();
ctx.moveTo(300, 300);
ctx.lineTo(400, 300);
ctx.lineTo(400, 250);
ctx.lineTo(300, 250);
ctx.lineTo(300, 200);
ctx.lineTo(300, 150);
ctx.lineTo(300, 100);
ctx.closePath();
ctx.stroke();

// End the scene
ctx.restore();
