function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#1b395c");  // Green hills

  // Sunset gradient
  const sunrise = color("#ffebcd");  // Yellowish orange
  const sunset = color("#ffd700");  // Gold
  const midday = color("#66bb00");   // Green

  for (let x = 0; x <= width; x++) {
    let t = map(x, 0, width, 0, 1);  // Time of day
    let r = lerp(sunset.r, midday.r, t);
    let g = lerp(sunset.g, midday.g, t);
    let b = lerp(sunset.b, midday.b, t);

    fill(r, g, b, 200);  // Opacity
    circle(x, height/2, 10);  // Sun
  }

  // Hills
  let hillHeight = height * 0.3;
  for (let y = height/2 - hillHeight/2; y <= height/2 + hillHeight/2; y += 50) {
    fill("#57b76b");  // Green hills
    ellipse(width/2 - 100, y, 200, hillHeight);
  }
}
