function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#269b3d");

  let sunX = random(width / 2 - 50, width / 2 + 50);
  let sunY = height * 0.8;
  let sunRadius = 30;

  fill("#ffd700", 255); // Sun color in red

  // Draw the sun
  brush.beginShape(0.2);
  brush.vertex(sunX - sunRadius, sunY - sunRadius);
  brush.vertex(sunX + sunRadius, sunY - sunRadius);
  brush.vertex(sunX, sunY + sunRadius);
  brush.endShape(true);

  // Draw some clouds
