// Define the sunset color scheme
const sunsetColors = ["#feccbc", "#ffc107", "#ffb300", "#ff8c00"];

// Calculate the number of segments for each color gradient
const segments = 10;

// Loop through each segment and add the corresponding sunset colors
for (let i = 0; i < segments + 1; i++) {
  const colorIndex = Math.floor(i * sunsetColors.length / segments);
  const fillColor = sunsetColors[colorIndex];

  // Add a rectangle for each segment with different colors
  brush.noStroke();
  brush.fill(fillColor);
  brush.beginShape(0.3); // curvature
  brush.vertex((i * width) / segments, height / 2 - 100); // bottom left
  brush.vertex(((i + 1) * width) / segments, height / 2 - 100); // bottom right
  brush.vertex(((i + 1) * width) / segments, height / 2 + 100); // top right
  brush.vertex((i * width) / segments, height / 2 + 100); // top left
  brush.endShape(true);
}
