let colors = ["#7db6c2", "#56cbf9", "#4dd0ef", "#3498db", "#2ecc71"];
let angle;

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  colorMode(HSB, 360, 100, 100);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#0096ff");

  // Set the sun position
  let sunX = cos(angle) * width / 2;
  let sunY = sin(angle) * height / 2;

  // Draw the sun
  strokeWeight(2);
  fill("yellow");
  circle(sunX, sunY, 100);

  // Draw the hills
  for (let i = 0; i < 10; i++) {
    let hillHeight = map(noise(i), 0, 1, 0, height / 2);
    let hillAngle = random(TWO_PI);
    let hillRadius = map(noise(i + 5), 0, 1, 30, 100);
    push();
    translate(sin(hillAngle) * hillRadius, cos(hillAngle) * hillRadius);
    rotate(hillAngle + PI/2);
    fill(colors[i % colors.length], 50, 80);
    ellipse(0, 0, hillRadius * 2, hillHeight);
    pop();
  }

  // Update the angle
  angle += 0.02;
}
```

### Explanation:
1. **Setup Function**:
   - Creates a canvas of size 400x400 pixels in WebGL mode.
   - Sets the brush scaling to 2x.
   - Enables webGL mode.
   - Disables loop because we want to see the result immediately.

2. **Draw Function**:
   - Translates the canvas so that the origin is in the center.
   - Sets the background color to blue (`#0096ff`).

   - Calculates the position of the sun based on a sinusoidal wave.
   - Draws a yellow sun at that position.

   - Draws ten hills. Each hill has a unique texture and gradient that changes over time.
     - It starts with a red base color (`#7db6c2`) and transitions to a lighter shade (`#56cbf9`).
     - The hills have a radius that varies between 30 and 100 pixels.
     - The hills rise from the bottom and fall up the screen.
     - The hills move horizontally across the screen with a sinusoidal pattern.

   - Updates the angle variable to create a spinning effect.

