function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  brush.randomSeed(42); // For reproducibility
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#c9cc9c"); // Light green

  // Sunlight
  brush.fill("#ffd700", 150);
  brush.beginShape(0.4);
  brush.vertex(100, 400);
  brush.vertex(300, 400);
  brush.vertex(300, 200);
  brush.vertex(100, 200);
  brush.endShape(true);

  // Hills
  for (let i = 0; i < 10; i++) {
    let hillHeight = random(100, 200);
    let hillColor = "#" + colorString(random(0, 1), random(0, 1), random(0, 1)).substring(2);
    brush.fill(hillColor, 150);
    brush.beginShape(0.5);
    for (let j = 0; j <= 400; j += 5) {
      brush.vertex(j, height - hillHeight);
    }
    brush.endShape(true);
  }

  // Clouds
  for (let i = 0; i < 5; i++) {
    let cloudX = random(0, 400);
    let cloudY = random(0, 400);
    let cloudRadius = random(30, 50);
    brush.fill("#ffffff", 200);
    brush.beginShape(0.3);
    for (let j = 0; j <= 2 * Math.PI; j += 0.05) {
      let x = cloudX + cos(j) * cloudRadius;
      let y = cloudY + sin(j) * cloudRadius;
      brush.vertex(x, y);
    }
    brush.endShape(true);
  }

  // Mountains
  for (let i = 0; i < 5; i++) {
    let mountainHeight = random(50, 100);
    let mountainColor = "#" + colorString(random(0.5, 1), random(0.5, 1), random(0.5, 1)).substring(2);
    brush.fill(mountainColor, 150);
    brush.beginShape(0.6);
    for (let j = 0; j <= 400; j += 5) {
      brush.vertex(j, height - mountainHeight);
    }
    brush.endShape(true);
  }
}

function colorString(r, g, b) {
  return "#" + ((r << 16) | (g << 8) | b).toString(16);
}
