  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  brush.noStroke();

  // --- SKY ---
  // Top sky - warm twilight purple/violet
  brush.fill("#7d5a8a", 120);
  brush.fillBleed(0.6);
  brush.fillTexture(0.5, 0.3);
  brush.beginShape(0.2);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 120);
  brush.vertex(0, 140);
  brush.endShape(true);

  // Mid sky - coral/pink wash
  brush.fill("#d9717a", 130);
  brush.fillBleed(0.7);
  brush.beginShape(0.3);
  brush.vertex(0, 80);
  brush.vertex(400, 60);
  brush.vertex(400, 190);
  brush.vertex(0, 200);
  brush.endShape(true);

  // Lower sky - vibrant orange and gold
  brush.fill("#f29d52", 140);
  brush.fillBleed(0.8);
  brush.beginShape(0.3);
  brush.vertex(0, 140);
  brush.vertex(400, 130);
  brush.vertex(400, 260);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Horizon glow - bright yellow
  brush.fill("#f7d465", 160);
  brush.fillBleed(0.8);
  brush.beginShape(0.3);
  brush.vertex(0, 190);
  brush.vertex(400, 180);
  brush.vertex(400, 290);
  brush.vertex(0, 280);
  brush.endShape(true);

  // --- SUN ---
  // Outer sun glow
  brush.fill("#fae588", 110);
  brush.fillBleed(0.9);
  brush.circle(230, 195, 65);

  // Sun core
  brush.fill("#fff5c0", 200);
  brush.fillBleed(0.3);
  brush.fillTexture(0.2, 0.1);
  brush.circle(230, 195, 32);

  // --- CLOUDS ---
  brush.fill("#8c587c", 90);
  brush.fillBleed(0.5);
  brush.fillTexture(0.6, 0.4);

  // Left cloud
  brush.beginShape(0.5);
  brush.vertex(20, 90);
  brush.vertex(90, 80);
  brush.vertex(150, 95);
  brush.vertex(80, 110);
  brush.endShape(true);

  // Right cloud
  brush.beginShape(0.5);
  brush.vertex(270, 120);
  brush.vertex(340, 105);
  brush.vertex(390, 120);
